-- 小程序历史表补「归档时间」(2026-11-24)：真多端互通的状态面。
-- 立因：web / RN 的会话可归档(chat_conversations.archived_at)，小程序这张历史表没有对应位，
-- 于是"归档"成了只在两端存在的维度。补同名列后，任一端归档都能被另一端看见。
--
-- 取值约束：可空时间戳(null = 未归档)，与 web 同一口径(布尔表达不了「何时归档」)；
-- 存量行零回填、行为零变化；写入面走 POST /api/ai/history/batch-archive 并镜像回统一表。

alter table "zhs_ai_user_model_chat_history" add column if not exists "archived_at" timestamp with time zone;
--> statement-breakpoint
comment on column "zhs_ai_user_model_chat_history"."archived_at" is '归档时间(2026-11-24): null=未归档,与 web chat_conversations.archived_at 同语义';
